//! Synthetic native semantics. Fresh real-engine/three-backend games remain Root work.
use super::*;
fn catalogue()->Value {serde_json::from_slice(include_bytes!(concat!(env!("OUT_DIR"),"/catalogue.json"))).unwrap()}
fn engine(backend:RulesBackend)->Engine {let mut e=Engine::from_catalogue_value(&catalogue()).unwrap();assert!(e.by_code.contains_key("SEC_040"),"{:?}",e.rejected_cards().unwrap().get("SEC_040"));e.set_rules_backend(backend).unwrap();e}
fn add(e:&Engine,s:&mut State,seat:Seat,code:&str)->CardId {let id=s.next_id;s.next_id+=1;*s.card_mut(id)=Card{present:true,def:*e.by_code.get(code).unwrap_or_else(||panic!("{code}")),owner:seat,..Card::default()};id}
fn unit(e:&Engine,s:&mut State,seat:Seat,code:&str)->CardId {let id=add(e,s,seat,code);e.add_arena(s,id).unwrap();id}
fn board(e:&Engine,seat:Seat)->State {let mut s=State::default();s.active=seat;s.action_player=Some(seat);s.hidden_history_exact=true;s.force_state_exact=true;s.credit_state_exact=true;s.round_limit_wire_present=true;for owner in [seat,seat.other()] {s.player_mut(owner).base=add(e,&mut s,owner,"SOR_023");s.player_mut(owner).leader=add(e,&mut s,owner,"SOR_014");s.player_mut(owner).force_id=add(e,&mut s,owner,"TOKEN_THE_FORCE");for _ in 0..24 {let id=add(e,&mut s,owner,"LOF_254");s.player_mut(owner).resources.push(id).unwrap();}for _ in 0..5 {let id=add(e,&mut s,owner,"LOF_254");s.player_mut(owner).deck.push(id).unwrap();}}s}
fn click(e:&Engine,s:&mut State,label:&str) {let a=e.legal_actions(s).into_iter().find(|a|a.label==label).unwrap_or_else(||panic!("missing {label}: {:?}",e.legal_actions(s)));*s=e.apply(s,&a).unwrap();}
fn start(e:&Engine,s:&mut State,source:CardId) {s.source=source;s.active=s.card(source).owner;let p=e.card_programs(s,source)[0];e.begin_program(s,p,ProgramContinuation::Finish).unwrap();}

#[test]fn resource_number_closed_source_and_standalone_guards(){
 let raw=crate::resource_number_experience_contract::profile();assert_eq!(crate::resource_number_experience_contract::prepare(&raw),Ok(true));
 for path in ["/sourceHash","/className","/setCode","/baseClass","/card/types","/card/cost","/abilities/card/0/targetResolver/type","/abilities/card/0/then/body/targetResolver/max","/abilities/card/0/then/body/effect/effects/0/allowCostAdjustments","/abilities/card/0/then/body/effect/effects/1/target","/abilities/card/0/then/body/thenCondition/right/type"]{let mut bad=raw.clone();*bad.pointer_mut(path).unwrap()=json!("foreign");assert!(crate::resource_number_experience_contract::prepare(&bad).is_err(),"{path}");}
 for path in ["","/abilities/card/0","/abilities/card/0/targetResolver","/abilities/card/0/then","/abilities/card/0/then/body/effect"]{let mut bad=raw.clone();bad.pointer_mut(path).unwrap().as_object_mut().unwrap().insert("unknown".into(),json!(true));assert!(crate::resource_number_experience_contract::prepare(&bad).is_err());}
 let mut mixed=raw.clone();mixed["abilities"]["card"].as_array_mut().unwrap().push(raw["abilities"]["card"][0].clone());assert!(crate::resource_number_experience_contract::prepare(&mixed).is_err());assert!(serde_json::from_value::<crate::ability_ir::Ability>(raw["abilities"]["card"][0].clone()).is_err());
 let e=engine(RulesBackend::Auto);let mut s=board(&e,Seat::P1);let source=add(&e,&mut s,Seat::P1,"SEC_040");let id=e.card_programs(&s,source)[0];assert!(crate::resource_number_experience_contract::program(e.program(id)));assert_eq!(std::mem::size_of::<State>(),38312);
}
fn choose_recipient(e:&Engine,s:&mut State,target:CardId){if s.decision==Decision::AbilityTarget {let action=e.legal_actions(s).into_iter().find(|a|a.card.as_deref()==Some(e.card_ref(s,target)["id"].as_str().unwrap_or(""))).or_else(||e.legal_actions(s).into_iter().find(|a|a.card.as_deref()==Some(&format!("c{target}")))).unwrap_or_else(||panic!("target {target}: {:?}",e.legal_actions(s)));*s=e.apply(s,&action).unwrap();}}
#[test]fn resource_number_normal_paid_event_captures_enemy_and_full_number_domain(){
 for backend in [RulesBackend::Auto,RulesBackend::Interpreter]{let e=engine(backend);for seat in [Seat::P1,Seat::P2]{for n in [0u8,1,7,19]{let mut s=board(&e,seat);let target=unit(&e,&mut s,seat.other(),"HMW_135");let source=add(&e,&mut s,seat,"SEC_040");s.player_mut(seat).hand.push(source).unwrap();let action=e.card_action(&s,source);s=e.apply(&s,&action).unwrap();choose_recipient(&e,&mut s,target);assert_eq!(s.decision,Decision::AbilityNumber);assert_eq!(e.ready_resources(&s,seat),19);let choices=e.legal_actions(&s);assert_eq!(choices.len(),20);assert_eq!(choices.last().unwrap().label,"#19");assert!(!choices.iter().any(|a|a.label=="Cancel"));let old=s;let hash=s.zobrist();assert!(e.snapshot(&s)["numberSelectionPending"]==true);assert!(e.load_state(&e.snapshot(&s)).is_err());let a=choices.into_iter().find(|a|a.label==format!("#{n}")).unwrap();s=e.apply(&s,&a).unwrap();assert_eq!(old.zobrist(),hash);assert_eq!(e.ready_resources(&s,seat),19-usize::from(n));assert_eq!(e.token_count(&s,s.card(target).experience),u16::from(n));assert!(s.player(seat).discard.contains(source));assert_eq!(s.selected_number,0);assert_eq!(s.decision,Decision::Window);}}}
}
#[test]fn resource_number_leader_only_continues_no_units_skips_and_zero_no_creation(){
 let e=engine(RulesBackend::Auto);for seat in [Seat::P1,Seat::P2]{let mut s=board(&e,seat);let leader=s.player(seat.other()).leader;s.card_mut(leader).deployed=true;e.add_arena(&mut s,leader).unwrap();let source=add(&e,&mut s,seat,"SEC_040");s.player_mut(seat).hand.push(source).unwrap();s=e.apply(&s,&e.card_action(&s,source)).unwrap();assert_eq!(s.decision,Decision::AbilityNumber);assert_eq!(s.ability_target,0);let next=s.next_id;click(&e,&mut s,"#7");assert_eq!(e.ready_resources(&s,seat),12);assert_eq!(s.next_id,next);assert_eq!(s.card(leader).experience,0);
 let mut s=board(&e,seat);let source=add(&e,&mut s,seat,"SEC_040");s.player_mut(seat).hand.push(source).unwrap();s=e.apply(&s,&e.card_action(&s,source)).unwrap();assert_eq!(s.decision,Decision::AbilityNoEffect);click(&e,&mut s,"Play anyway");assert_eq!(s.decision,Decision::Window);assert_eq!(e.ready_resources(&s,seat),19);}
}
#[test]fn resource_number_storage_last_bound_and_atomic_capacity(){
 let e=engine(RulesBackend::Auto);let mut s=board(&e,Seat::P1);let target=unit(&e,&mut s,Seat::P2,"HMW_135");let source=add(&e,&mut s,Seat::P1,"SEC_040");while s.player(Seat::P1).resources.as_slice().len()<MAX_ZONE {let id=add(&e,&mut s,Seat::P1,"LOF_254");s.player_mut(Seat::P1).resources.push(id).unwrap();}s.source=source;start(&e,&mut s,source);choose_recipient(&e,&mut s,target);assert_eq!(s.decision,Decision::AbilityNumber);assert_eq!(e.number_actions(&s).len(),65);for encoded in [0,66,255] {let mut bad=s;bad.selected_number=encoded;bad.ability_pc=2;let old=bad;assert!(e.run_number_instruction(&mut bad).is_err());assert_eq!(bad,old);}
 let mut full=s;full.next_id=(MAX_CARDS-1) as u16;let old=full;let a=e.number_actions(&full).into_iter().find(|a|a.label=="#7").unwrap();assert!(e.apply(&full,&a).is_err());assert_eq!(full,old);click(&e,&mut s,"#64");assert_eq!(e.ready_resources(&s,Seat::P1),0);assert_eq!(e.token_count(&s,s.card(target).experience),64);
}

#[test]fn resource_number_printed_cost_credit_then_unadjusted_payment_and_cancel(){
 let e=engine(RulesBackend::Auto);for seat in [Seat::P1,Seat::P2]{
 let mut s=board(&e,seat);let target=unit(&e,&mut s,seat,"HMW_135");let source=add(&e,&mut s,seat,"SEC_040");s.player_mut(seat).hand.push(source).unwrap();e.create_credit_tokens(&mut s,seat,1).unwrap();let original=s;let a=e.card_action(&s,source);s=e.apply(&s,&a).unwrap();assert_eq!(s.decision,Decision::AbilityTarget);click(&e,&mut s,"Cancel");assert_eq!(s.player(seat).hand,original.player(seat).hand);assert_eq!(e.ready_resources(&s,seat),24);assert_eq!(s.card(target).experience,0);
 s=e.apply(&s,&e.card_action(&s,source)).unwrap();choose_recipient(&e,&mut s,target);assert_eq!(s.decision,Decision::CreditMenu);click(&e,&mut s,"Use 1 Credit");assert_eq!(s.decision,Decision::AbilityNumber);assert_eq!(e.ready_resources(&s,seat),20);e.create_credit_tokens(&mut s,seat,2).unwrap();let credits=s.player(seat).credits;click(&e,&mut s,"#7");assert_eq!(e.ready_resources(&s,seat),13);assert_eq!(s.player(seat).credits,credits);assert_eq!(e.token_count(&s,s.card(target).experience),7);
 }}
#[test]fn resource_number_complete_constructor_delta(){
 let Ok(path)=std::env::var("SWU_SEC040_BASELINE_POOL") else {return;};let old:Value=serde_json::from_slice(&std::fs::read(path).unwrap()).unwrap();let e=engine(RulesBackend::Auto);let new=e.compiled_pool().unwrap();let codes=|v:&Value|v["cards"].as_array().unwrap().iter().map(|r|r["setCode"].as_str().unwrap().to_owned()).collect::<std::collections::BTreeSet<_>>();let(a,b)=(codes(&old),codes(&new));assert_eq!(b.difference(&a).map(String::as_str).collect::<Vec<_>>(),vec!["SEC_040"]);assert!(a.is_subset(&b));eprintln!("SEC040_CONSTRUCTOR old={} new={} gained=SEC_040 lost=0",a.len(),b.len());
 if let Ok(out)=std::env::var("SWU_SEC040_REPORT_DIR"){std::fs::create_dir_all(&out).unwrap();std::fs::write(std::path::Path::new(&out).join("pool.json"),serde_json::to_vec_pretty(&new).unwrap()).unwrap();std::fs::write(std::path::Path::new(&out).join("rules.json"),serde_json::to_vec_pretty(&e.rules_backend_report()).unwrap()).unwrap();}
}

#[test]fn resource_number_simultaneous_attachment_window_observes_all_xp_after_payment(){
 for backend in [RulesBackend::Auto,RulesBackend::Interpreter]{let e=engine(backend);for seat in [Seat::P1,Seat::P2]{let mut s=board(&e,seat);let target=unit(&e,&mut s,seat,"ASH_208");let other=unit(&e,&mut s,seat.other(),"HMW_135");let source=add(&e,&mut s,seat,"SEC_040");s.player_mut(seat).hand.push(source).unwrap();s=e.apply(&s,&e.card_action(&s,source)).unwrap();choose_recipient(&e,&mut s,target);click(&e,&mut s,"#7");assert_eq!(e.token_count(&s,s.card(target).experience),7);assert_eq!(e.ready_resources(&s,seat),12);assert!(e.legal_actions(&s).contains(&e.card_action(&s,other)));assert_eq!(e.program(s.ability_program-1).trigger,"onUpgradeAttached");let a=e.card_action(&s,other);s=e.apply(&s,&a).unwrap();assert!(s.card(other).exhausted);assert_eq!(s.decision,Decision::Window);}}
}
#[test]fn resource_number_missing_native_xp_and_copied_program_mutants_reject(){
 let mut c=catalogue();c["cards"].as_array_mut().unwrap().retain(|r|r["setCode"]!="TOKEN_EXPERIENCE");let e=Engine::from_catalogue_value(&c).unwrap();assert!(!e.by_code.contains_key("SEC_040"));
 let e=engine(RulesBackend::Auto);let mut s=board(&e,Seat::P1);let source=add(&e,&mut s,Seat::P1,"SEC_040");s.source=source;let p=e.card_programs(&s,source)[0];for mutation in 0..3 {let mut bad=e.program(p).clone();match mutation{0=>bad.optional=true,1=>{bad.instructions.remove(0);},_=>{bad.event_end=3;}};assert!(!crate::resource_number_experience_contract::program(&bad));}
}

#[test]fn resource_number_binding_sentinel_and_context_copy_hash(){
 let e=engine(RulesBackend::Auto);let mut s=board(&e,Seat::P1);let source=add(&e,&mut s,Seat::P1,"SEC_040");s.source=source;let p=e.card_programs(&s,source)[0];s.ability_program=p+1;s.ability_pc=2;
 let mut hashes=std::collections::BTreeSet::new();for encoded in [0u8,1,65]{s.selected_number=encoded;hashes.insert(s.zobrist());let context=ResolutionContext::capture(&s);let mut copy=s;copy.selected_number=0;context.restore(&mut copy);assert_eq!(copy,s);assert_eq!(copy.zobrist(),s.zobrist());}assert_eq!(hashes.len(),3);assert_eq!(std::mem::size_of::<ResolutionContext>(),124);
}
